#!/usr/bin/env node
/**
 * build-classroom-config.js
 *
 * Generates assets/js/behistorical-classroom.js from
 * scripts/lib/classroom-config.js, then inlines it into the two lesson
 * renderers and the BeInTheRoom v2 room renderer between sentinels, the same
 * way build-coach-prompt.js inlines the coach prompt builder.
 *
 * WHY GENERATE AND THEN INLINE
 *
 * The generated file is what the 77 capture wrappers and the 77 First & 10
 * readings load with a plain `<script src>`, since both are already generated
 * pages. The two renderers and behistorical-room-v2.js are loaded by hundreds
 * of hand-authored shells and scenario pages instead, so adding a `<script
 * src>` to every one of them would be a sweep across hundreds of files.
 * Inlining reaches all of them with no shell change at all, at the cost of a
 * derived copy, which is what the drift check below is for.
 *
 * Usage: node scripts/build-classroom-config.js [--check]
 */

'use strict';

const fs = require('fs');
const path = require('path');
const { CLASSROOMS } = require('./lib/classroom-config');

const ROOT = path.join(__dirname, '..');
const GENERATED = path.join(ROOT, 'assets', 'js', 'behistorical-classroom.js');
const CHECK = process.argv.includes('--check');

// Loaded by hundreds of shells and scenario pages each, so a fourth `<script
// src>` is a sweep; inlining is not.
const INLINE_TARGETS = [
  path.join(ROOT, 'assets', 'js', 'behistorical-topic-renderer-v1.js'),
  path.join(ROOT, 'foundations', 'foundations-topic-renderer.js'),
  path.join(ROOT, 'assets', 'js', 'behistorical-room-v2.js')
];

const OPEN = '// ── BEGIN INLINED CLASSROOM CONFIG ──────────────────────────────────────────';
const CLOSE = '// ── END INLINED CLASSROOM CONFIG ────────────────────────────────────────────';

function generatedSource() {
  return `// BeHistorical serves two AP World History sections through one shared site,
// each running its own MagicSchool Socrates classroom. This resolves which
// MagicSchool join link a student's AI Coach / Open MagicSchool buttons
// should use, so the two sections never land in each other's classroom.
//
// A student's classroom is chosen once, by the link their own teacher gives
// them (?classroom=<key>), and stays remembered on that device from then on.
// A student who never sees that link resolves to whatever default the caller
// passes in, unchanged.
//
// Generated by scripts/build-classroom-config.js from
// scripts/lib/classroom-config.js. Do not hand-edit: the offline suite
// re-derives this file and fails the push on drift. Change the source data
// and rebuild.
(function (global) {
  'use strict';

  var STORAGE_KEY = 'behistorical-classroom';
  var CLASSROOMS = ${JSON.stringify(CLASSROOMS)};

  function currentClassroomUrl() {
    try {
      var params = new URLSearchParams(global.location.search);
      var fromLink = params.get('classroom');
      if (fromLink && CLASSROOMS[fromLink]) {
        global.localStorage.setItem(STORAGE_KEY, fromLink);
        return CLASSROOMS[fromLink];
      }
      var remembered = global.localStorage.getItem(STORAGE_KEY);
      if (remembered && CLASSROOMS[remembered]) return CLASSROOMS[remembered];
    } catch (error) {
      // Private browsing, or localStorage blocked: fall through to the default.
    }
    return null;
  }

  function resolveMagicSchoolUrl(defaultUrl) {
    return currentClassroomUrl() || defaultUrl;
  }

  global.BHClassroom = { resolveMagicSchoolUrl: resolveMagicSchoolUrl };
})(window);
`;
}

function inlinedBlock() {
  const src = generatedSource().trimEnd();
  return [
    OPEN,
    '//',
    '// Derived from assets/js/behistorical-classroom.js by',
    '// scripts/build-classroom-config.js. Do not hand-edit: the offline suite',
    '// re-derives this block and fails the push on drift. Change the source data',
    '// and rebuild.',
    src,
    CLOSE
  ].join('\n');
}

let drift = 0;
let wrote = 0;

// 1. The standalone generated file, loaded by <script src> from the capture
//    wrappers and the 77 readings.
{
  const current = fs.existsSync(GENERATED) ? fs.readFileSync(GENERATED, 'utf8') : null;
  const next = generatedSource();
  if (CHECK) {
    if (current !== next) {
      console.error('DRIFT assets/js/behistorical-classroom.js no longer matches scripts/lib/classroom-config.js.');
      drift++;
    }
  } else if (current !== next) {
    fs.writeFileSync(GENERATED, next);
    wrote++;
    console.log('wrote assets/js/behistorical-classroom.js');
  }
}

// 2. The inlined copies, for the two renderers and the BeInTheRoom v2
//    renderer, none of which can add a script tag without a sweep across
//    every page that loads them.
for (const TARGET of INLINE_TARGETS) {
  const rel = path.relative(ROOT, TARGET);
  const target = fs.readFileSync(TARGET, 'utf8');
  const start = target.indexOf(OPEN);
  const end = target.indexOf(CLOSE);

  if (start === -1 || end === -1) {
    console.error(`FAIL ${rel} has no classroom-config sentinels.`);
    console.error('Add these two lines around the inlined region, then rebuild:');
    console.error(`  ${OPEN}`);
    console.error(`  ${CLOSE}`);
    process.exit(1);
  }

  const rebuilt = target.slice(0, start) + inlinedBlock() + target.slice(end + CLOSE.length);

  if (CHECK) {
    if (rebuilt !== target) {
      console.error(`DRIFT ${rel}: the inlined classroom config no longer matches`
        + ' assets/js/behistorical-classroom.js.');
      drift++;
    }
  } else if (rebuilt !== target) {
    fs.writeFileSync(TARGET, rebuilt);
    wrote++;
    console.log(`wrote ${rel}`);
  }
}

if (CHECK) {
  if (drift) {
    console.error('Run: node scripts/build-classroom-config.js');
    process.exit(1);
  }
  console.log(`classroom config: generated file and ${INLINE_TARGETS.length} inlined copies match source`);
} else {
  console.log(wrote ? `updated ${wrote} file(s)` : 'classroom config: already current');
}
